import { loadRules } from './helpers/rules.js'
import { describe, it, beforeAll, afterAll, beforeEach } from 'vitest'
import { initializeTestEnvironment, assertFails, assertSucceeds } from '@firebase/rules-unit-testing'
import { doc, setDoc, getDoc, updateDoc, deleteDoc, runTransaction } from 'firebase/firestore'

// Certificate of Eligibility (2026-11-16): generated by the case hospital's
// gateway staff, content frozen, signed scan + void only; read by the
// hospital, the patient and agencies endorsed on the request. Numbers come
// from a per-hospital yearly counter that only moves up by one.
const A = 'hospital-a'
const B = 'hospital-b'
const CNO = 'A-COE-2026-00001'
const CID = `r1__${CNO}`
let testEnv

beforeAll(async () => {
  testEnv = await initializeTestEnvironment({
    projectId: 'mapa-rules-test-eligibility-cert',
    firestore: { rules: loadRules(), host: 'localhost', port: 8080 },
  })
})
afterAll(async () => testEnv?.cleanup())

beforeEach(async () => {
  await testEnv.clearFirestore()
  await testEnv.withSecurityRulesDisabled(async (ctx) => {
    const db = ctx.firestore()
    const put = (p, d) => setDoc(doc(db, ...p.split('/')), d)
    await Promise.all([
      put('users/adminA', { role: 'staff_admin', tenantId: A }),
      put('users/adminB', { role: 'staff_admin', tenantId: B }),
      put('users/coord', { role: 'agency', agencyId: 'dswd' }),
      put('users/other', { role: 'agency', agencyId: 'pcso' }),
      put('users/pat', { role: 'patient', tenantId: A, tenantIds: [A] }),
      put('users/pat2', { role: 'patient', tenantId: A, tenantIds: [A] }),
      put('requests/r1', { tenantId: A, patientId: 'pat', agencyIds: ['dswd'], status: 'endorsed' }),
    ])
  })
})

const as = (uid) => testEnv.authenticatedContext(uid).firestore()
const cert = (extra = {}) => ({
  tenantId: A, requestId: 'r1', patientId: 'pat', controlNo: CNO, snapshot: { controlNo: CNO },
  status: 'generated', signed: null, voided: null, generatedBy: 'A', generatedByUid: 'adminA', ...extra,
})
const seed = (data = cert()) => testEnv.withSecurityRulesDisabled(async (ctx) => setDoc(doc(ctx.firestore(), 'eligibilityCertificates', CID), data))

describe('eligibilityCertificates', () => {
  it('the case hospital generates one', async () => {
    await assertSucceeds(setDoc(doc(as('adminA'), 'eligibilityCertificates', CID), cert()))
  })
  it('refuses another hospital, a mismatched id or patient, or a pre-signed certificate', async () => {
    await assertFails(setDoc(doc(as('adminB'), 'eligibilityCertificates', CID), cert({ tenantId: B, generatedByUid: 'adminB' })))
    await assertFails(setDoc(doc(as('adminA'), 'eligibilityCertificates', 'r1__WRONG'), cert()))
    await assertFails(setDoc(doc(as('adminA'), 'eligibilityCertificates', CID), cert({ patientId: 'pat2' })))
    await assertFails(setDoc(doc(as('adminA'), 'eligibilityCertificates', CID), cert({ status: 'signed' })))
    await assertFails(setDoc(doc(as('adminA'), 'eligibilityCertificates', CID), cert({ signed: { base64: 'x' } })))
    await assertFails(setDoc(doc(as('pat'), 'eligibilityCertificates', CID), cert()))
  })
  it('is read by the hospital, its patient and endorsed agencies only', async () => {
    await seed()
    await assertSucceeds(getDoc(doc(as('adminA'), 'eligibilityCertificates', CID)))
    await assertSucceeds(getDoc(doc(as('pat'), 'eligibilityCertificates', CID)))
    await assertSucceeds(getDoc(doc(as('coord'), 'eligibilityCertificates', CID)))
    await assertFails(getDoc(doc(as('other'), 'eligibilityCertificates', CID)))
    await assertFails(getDoc(doc(as('pat2'), 'eligibilityCertificates', CID)))
    await assertFails(getDoc(doc(as('adminB'), 'eligibilityCertificates', CID)))
  })
  it('only the signed scan, status and void change; content is fixed; never deleted', async () => {
    await seed()
    await assertSucceeds(updateDoc(doc(as('adminA'), 'eligibilityCertificates', CID), { signed: { base64: 'data:x' }, status: 'signed' }))
    await assertFails(updateDoc(doc(as('adminA'), 'eligibilityCertificates', CID), { snapshot: { controlNo: 'X' } }))
    await assertFails(updateDoc(doc(as('adminA'), 'eligibilityCertificates', CID), { patientId: 'pat2' }))
    await assertFails(updateDoc(doc(as('pat'), 'eligibilityCertificates', CID), { status: 'voided' }))
    await assertSucceeds(updateDoc(doc(as('adminA'), 'eligibilityCertificates', CID), { status: 'voided', voided: { reason: 'wrong diagnosis' } }))
    await assertFails(updateDoc(doc(as('adminA'), 'eligibilityCertificates', CID), { status: 'signed' }))   // a void is final
    await assertFails(deleteDoc(doc(as('adminA'), 'eligibilityCertificates', CID)))
  })
})

describe('eligibilityCounters', () => {
  const ref = (db) => doc(db, 'eligibilityCounters', `${A}__2026`)
  it('starts at 2 and only moves up by one, inside the hospital', async () => {
    const db = as('adminA')
    await assertSucceeds(runTransaction(db, async (tx) => {
      const c = await tx.get(ref(db))
      if (!c.exists()) tx.set(ref(db), { tenantId: A, year: 2026, next: 2 })
    }))
    await assertSucceeds(updateDoc(ref(db), { next: 3 }))
    await assertFails(updateDoc(ref(db), { next: 10 }))
    await assertFails(updateDoc(ref(as('adminB')), { next: 4 }))
    await assertFails(setDoc(doc(as('adminA'), 'eligibilityCounters', `${B}__2026`), { tenantId: A, year: 2026, next: 2 }))
    await assertFails(getDoc(ref(as('pat'))))
  })
})

describe('hospitalSettings (citation and noted-by)', () => {
  const setSuper = () => testEnv.withSecurityRulesDisabled(async (ctx) => setDoc(doc(ctx.firestore(), 'users', 'superA'), { role: 'super_admin', tenantId: A }))
  it('accepts the citation, status and noted-by fields', async () => {
    await setSuper()
    await assertSucceeds(setDoc(doc(as('superA'), 'hospitalSettings', A), {
      tenantId: A, povertyLinePerCapita: 2577, povertyLineYear: 2023, region: 'BARMM',
      povertyLineCitation: 'PSA 2023 FY…', povertyLineCitationShort: 'PSA 2023', povertyLineStatus: 'interim',
      coeNotedByName: 'Maria Santos, RSW', coeNotedByTitle: 'Head, MSS',
    }))
    await assertFails(setDoc(doc(as('superA'), 'hospitalSettings', A), { tenantId: A, povertyLineStatus: 'final' }, { merge: true }))
    await assertFails(setDoc(doc(as('superA'), 'hospitalSettings', A), { tenantId: A, coeNotedByName: 'x'.repeat(101) }, { merge: true }))
  })
})
